package com.lqq.supportflow.ticket.infrastructure.persistence;
import com.lqq.supportflow.ticket.domain.*; import java.time.*; import org.springframework.stereotype.Component;
@Component public class MyBatisTicketAdapter implements TicketPort { private final TicketMapper mapper; public MyBatisTicketAdapter(TicketMapper mapper){this.mapper=mapper;} public Ticket create(Long tenantId,Long customerId,Long conversationId,String title,TicketPriority priority){Instant now=Instant.now();TicketEntity entity=new TicketEntity();entity.tenantId=tenantId;entity.customerId=customerId;entity.conversationId=conversationId;entity.title=title;entity.status=TicketStatus.NEW.name();entity.priority=priority.name();entity.firstResponseDueAt=now.plus(firstResponse(priority));entity.resolutionDueAt=now.plus(resolution(priority));entity.version=0L;entity.createdAt=now;entity.updatedAt=now;mapper.insert(entity);return new Ticket(entity.id,TicketStatus.NEW,priority,entity.firstResponseDueAt,entity.resolutionDueAt);} private Duration firstResponse(TicketPriority priority){return switch(priority){case LOW->Duration.ofHours(8);case NORMAL->Duration.ofHours(4);case HIGH->Duration.ofHours(1);case URGENT->Duration.ofMinutes(15);};} private Duration resolution(TicketPriority priority){return switch(priority){case LOW->Duration.ofHours(72);case NORMAL->Duration.ofHours(48);case HIGH->Duration.ofHours(12);case URGENT->Duration.ofHours(4);};}}
